 static string FileAt(string root,string relative,DateTime time){string p=Path.GetFullPath(Path.Combine(root,relative));Directory.CreateDirectory(Path.GetDirectoryName(p));File.WriteAllText(p,"fixture, not an executable");File.SetLastWriteTimeUtc(p,time);return p;}
 static IEnumerable<Control> All(Control parent){foreach(Control c in parent.Controls){yield return c;foreach(var x in All(c))yield return x;}}
