 static string Mock(string root,string mode){string source=Path.Combine(root,"mock-"+mode+".cs"),exe=Path.ChangeExtension(source,".exe");string body=mode=="rpc"?"Console.WriteLine(\"{\\\"id\\\":\"+id+\",\\\"error\\\":{\\\"message\\\":\\\"PRIVATE_RAW_ERROR_DO_NOT_SHOW\\\"}}\");":mode=="invalid"?"Console.WriteLine(\"{\\\"id\\\":\"+id+\",\\\"result\\\":{}}\");":"System.Threading.Thread.Sleep(5000);";
 string code="using System;using System.Collections.Generic;using System.Web.Script.Serialization;class MockCli{static void Main(){var j=new JavaScriptSerializer();string line;while((line=Console.ReadLine())!=null){var d=j.Deserialize<Dictionary<string,object>>(line);if(!d.ContainsKey(\"id\"))continue;string id=d[\"id\"].ToString();if((string)d[\"method\"]==\"initialize\")Console.WriteLine(\"{\\\"id\\\":\"+id+\",\\\"result\\\":{}}\");else{"+body+"}}}}";File.WriteAllText(source,code,Encoding.UTF8);
 var start=new ProcessStartInfo{FileName=Path.Combine(System.Runtime.InteropServices.RuntimeEnvironment.GetRuntimeDirectory(),"csc.exe"),Arguments="/nologo /target:exe /reference:System.Web.Extensions.dll /out:\""+exe+"\" \""+source+"\"",UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var p=Process.Start(start)){string output=p.StandardOutput.ReadToEnd();string errors=p.StandardError.ReadToEnd();p.WaitForExit();if(p.ExitCode!=0)throw new Exception("Mock compilation failed: "+output+errors);}return exe;}
