 if(args.Length==1&&args[0]=="--live-desktop"){string local=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);string missing=Path.Combine(Path.GetTempPath(),"no-npm-"+Guid.NewGuid().ToString("N"));string chosen=LiveUsage.FindExecutable(missing,local);Check(chosen.StartsWith(Path.Combine(local,"OpenAI","Codex","bin"),StringComparison.OrdinalIgnoreCase),"desktop-only discovery");using(var live=new LiveUsage(()=>LiveUsage.FindExecutable(missing,local))){var sample=live.Read();Check(sample.Official&&sample.Source=="account/rateLimits/read"&&(sample.Primary!=null||sample.Secondary!=null),"real desktop CLI official quota read");}Console.WriteLine("PASS: desktop-bundled CLI real account/rateLimits/read; no account values or paths logged");return;}
 string root=Path.Combine(Environment.CurrentDirectory,"cd-"+Guid.NewGuid().ToString("N").Substring(0,12));Directory.CreateDirectory(root);string roam=Path.Combine(root,"roam"),localRoot=Path.Combine(root,"local");var old=new DateTime(2026,1,1,0,0,0,DateTimeKind.Utc);
 try{try{LiveUsage.FindExecutable(roam,localRoot);throw new Exception("missing CLI accepted");}catch(CodexReadException e){Check(e.Code=="cli-not-found","missing layout has visible reason");}
 string desktop=FileAt(localRoot,"OpenAI/Codex/bin/zzz-old/codex.exe",old);Check(LiveUsage.FindExecutable(roam,localRoot)==desktop,"desktop-only computer supported");string newest=FileAt(localRoot,"OpenAI/Codex/bin/aaa-new/codex.exe",old.AddDays(2));Directory.SetLastWriteTimeUtc(Path.GetDirectoryName(desktop),old.AddDays(20));Check(LiveUsage.FindExecutable(roam,localRoot)==newest,"file timestamp, not directory name or timestamp");Directory.CreateDirectory(Path.Combine(localRoot,"OpenAI/Codex/bin/empty-version"));Check(LiveUsage.FindExecutable(roam,localRoot)==newest,"incomplete upgrade directory ignored");string upgraded=FileAt(localRoot,"OpenAI/Codex/bin/000-upgrade/codex.exe",old.AddDays(3));Check(LiveUsage.FindExecutable(roam,localRoot)==upgraded,"new version directory discovered without cached path");File.Delete(upgraded);Check(LiveUsage.FindExecutable(roam,localRoot)==newest,"removed update falls back");string renamed=Path.Combine(Path.GetDirectoryName(Path.GetDirectoryName(newest)),"renamed-version");Directory.Move(Path.GetDirectoryName(newest),renamed);Check(LiveUsage.FindExecutable(roam,localRoot)==Path.Combine(renamed,"codex.exe"),"renamed opaque version supported");
 string npm=FileAt(roam,"npm/node_modules/@openai/codex/node_modules/@openai/codex-win32-x64/vendor/x86_64-pc-windows-msvc/bin/codex.exe",old);Check(LiveUsage.FindExecutable(roam,localRoot)==npm,"existing npm choice remains preferred even when desktop is newer");File.Delete(npm);Check(LiveUsage.FindExecutable(roam,localRoot)==Path.Combine(renamed,"codex.exe"),"npm removal falls back to desktop");
 using(var client=new LiveUsage(()=>{throw new CodexReadException("cli-not-found");}))ExpectCode(client,"cli-not-found");using(var client=new LiveUsage(()=>Path.Combine(root,"absent.exe")))ExpectCode(client,"cli-start");foreach(string mode in new[]{"rpc","invalid","timeout"})using(var client=new LiveUsage(()=>MockCache(root,mode))){client.ReadTimeoutMs=1200;ExpectCode(client,mode=="rpc"?"rpc-error":mode=="invalid"?"invalid-response":"timeout");}
 MeterPreferences.DirectoryOverride=Path.Combine(root,"preferences");SkinSettings.DirectoryOverride=Path.Combine(root,"skins");var now=DateTimeOffset.UtcNow;var snapshot=new Snapshot{Official=true,At=now,Primary=new QuotaWindow{Used=59,Reset=now.AddHours(5).ToUnixTimeSeconds()}};
 using(var form=new FloatingUsage(IntPtr.Zero,true)){form.Opacity=0;form.ShowInTaskbar=false;form.TopMost=false;form.Show();foreach(string skin in new[]{"A","B","C","D"})foreach(string language in new[]{"zh-CN","en"})foreach(string code in new[]{"cli-not-found","cli-start","timeout","rpc-error","invalid-response","read-failed"}){form.SelectSkins(skin,skin);form.TestLanguage(language);form.TestState(snapshot,false,1);form.TestFailure(code);bool found=false;foreach(Control c in All(form))if(c.Text.Contains(LiveUsage.ErrorText(code,language=="en")))found=true;Check(found,"failure reason visible for every skin/language");Check(object.ReferenceEquals(form.TestSnapshot,snapshot)&&form.TestSnapshot.Primary.Remaining==41,"failure preserves cached official quota");}}
 var state=new UsageState();state.Accept(snapshot);state.Fail(null,"cli-not-found");Check(state.Cached&&state.LastErrorCode=="cli-not-found","failed read retains source timestamp and error");state.Accept(snapshot);Check(!state.QueryFailed&&state.LastErrorCode==null,"recovery clears error");Console.WriteLine("PASS: "+checks+" discovery, upgrade, error-redaction, visible-error and cache assertions");
 }finally{string resolved=Path.GetFullPath(root),allowed=Path.GetFullPath(Environment.CurrentDirectory)+Path.DirectorySeparatorChar;if(!resolved.StartsWith(allowed,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(resolved).StartsWith("cd-",StringComparison.Ordinal))throw new Exception("Unsafe fixture cleanup path");Directory.Delete(resolved,true);}}
 static readonly Dictionary<string,string> mocks=new Dictionary<string,string>();static string MockCache(string root,string mode){string path;if(!mocks.TryGetValue(mode,out path)){path=Mock(root,mode);mocks[mode]=path;}return path;}
